from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    take_next = True
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse left to right
            for j in range(len(grid[i])):
                if take_next:
                    result.append(grid[i][j])
                take_next = not take_next
        else:
            # Traverse right to left
            for j in range(len(grid[i]) - 1, -1, -1):
                if take_next:
                    result.append(grid[i][j])
                take_next = not take_next
    return result

def findValidPair(s: str) -> str:
    counts = {str(i): 0 for i in range(1, 10)}
    for char in s:
        counts[char] += 1

    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            a, b = s[i], s[i + 1]
            if counts[a] == int(a) and counts[b] == int(b):
                return a + b
    return ""

