def maxSum(nums: List[int]) -> int:
    max_sum = float('-inf')

    for start in range(len(nums)):
        seen = set()
        subtotal = 0
        for end in range(start, len(nums)):
            if nums[end] in seen:
                break
            seen.add(nums[end])
            subtotal += nums[end]
            max_sum = max(max_sum, subtotal)

    return max_sum

