def reverseDegree(s: str) -> int:
    reverse_alphabet_value = {chr(i): 26 - (i - 97) for i in range(97, 123)}
    total = 0
    for index, char in enumerate(s):
        position_in_string = index + 1
        total += reverse_alphabet_value[char] * position_in_string
    return total

