def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    dp = [1] * n
    max_length = 1
    diffs = []

    for i in range(1, n):
        diffs.append(abs(nums[i] - nums[i-1]))

    for i in range(n):
        for j in range(i):
            if i > 0 and j > 0:
                if abs(nums[i] - nums[j]) >= diffs[j - 1]:
                    dp[i] = max(dp[i], dp[j] + 1)
            elif i > 0:
                dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])

    return max_length

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)
    mirror_map = {chr(i): chr(219 - i) for i in range(ord('a'), ord('z') + 1)}
    for i in range(len(s)):
        if marked[i]:
            continue
        mirror = mirror_map[s[i]]
        for j in range(i - 1, -1, -1):
            if s[j] == mirror and not marked[j]:
                score += i - j
                marked[i] = True
                marked[j] = True
                break
    return score

